            $this->faq('What telecommunications data should be migrated?', 'Validated customers, accounts, active subscribers and services, balances, deposits, open invoices, assets, dealers, agreements and selected history can be migrated after signed reconciliation.', 'کدام telecommunications data migrate شود؟', 'customer، account، active subscriber/service، balance، deposit، open invoice، asset، dealer، agreement و history انتخابی پس از reconciliation امضاشده منتقل می‌شود.', 'کوم telecommunications data ولېږدول شي؟', 'validated customer، account، active subscriber/service، balance، deposit، open invoice، asset، dealer، agreement او ټاکلی history له لاسلیک شوي reconciliation وروسته لېږدول کېږي.'),
            $this->faq('How is telecommunications OSS/BSS software priced?', 'Pricing depends on business lines, subscribers, services, users, billing and assurance depth, sites, channels, integrations, data volume, resilience, migration, deployment, training and support.', 'قیمت telecommunications OSS/BSS چگونه تعیین می‌شود؟', 'قیمت به business line، subscriber، service، user، billing/assurance depth، site، channel، integration، data volume، resilience، migration، deployment، training و support وابسته است.', 'د telecommunications OSS/BSS بیه څنګه ټاکل کېږي؟', 'بیه په business line، subscriber، service، user، billing/assurance depth، site، channel، integration، data volume، resilience، migration، deployment، training او support پورې تړلې ده.'),
